import React, { useState } from 'react';
import { Text, View, StyleSheet, Dimensions } from 'react-native';
import "./ImageGroup.css";
import { cell, COL, NSFW_MARKER, TV_EPISODE } from "../data/schema.js";

const ImageGroup = ({title, imageGroups, isVisible}) => {
	
	const screenWidth = Dimensions.get('window').width;
	
	const [isFullImage, setIsFullImage] = useState(false);
	const [fullImage, setFullImage] = useState(null);
	const [popupData, setPopupData] = useState(null);
	const [currentIndex, setCurrentIndex] = useState(0);
		
	const handleOpen = (data) => { setPopupData(data); setCurrentIndex(0)};
	const handleClose = () => { setPopupData(null); setCurrentIndex(0)};
	
	const handleFull = (image) => { setFullImage(image); setIsFullImage(true)};
	
	const showPrev = () => {
		setCurrentIndex((prev) => (prev - 1 + popupData.images.length) % popupData.images.length);
	};

	const showNext = () => {
		setCurrentIndex((prev) => (prev + 1) % popupData.images.length);
	};
	
	function LinkText({ text }) {
		const cleanedText = String(text ?? "").replace(/\[.*?\]/g, "");
		const urlRegex = /(https?:\/\/[^\s]+)/g;
		
		const parts = cleanedText.split(urlRegex);

	  return (
		<p className="extra-info">
		  {parts.map((part, index) =>
			urlRegex.test(part) ? (
			  <a key={index} href={part} target="_blank" rel="noopener noreferrer">
				{part}
			  </a>
			) : (
			  part
			)
		  )}
		</p>
	  );
	}
	
	
	const styles = StyleSheet.create({
		entryText: {
		color: 'white',
		textAlign: 'center',
		flex: 1,
		flexWrap: 'wrap',
		maxWidth: screenWidth < 500 ? '280px' : '380px',
		},
		conk: {
		  position: 'absolute',
		  top: '10px',
		  right: '10px',
		  padding: '10px 6px',
		  fontSize: '12px',
		  cursor: 'pointer',
		  backgroundColor: 'rgba(255, 255, 255, 0.5)',
		},
	});
	
	const returnStyle = (text) => ({
		 filter : String(text ?? '').includes(NSFW_MARKER) ? 'blur(8px)' : 'none',
	});
	
	function PrintInfo(entryInfo, idx){
		const who = cell(entryInfo, COL.WHO_WHAT);
		const series = cell(entryInfo, COL.SERIES);
		const when = cell(entryInfo, COL.WHEN);
		
		if(idx !== 0 || when.includes(TV_EPISODE)){
			return `${who} in ${series}\n(${when})`;
		}
		return `${who} in\n(${when})`;
		
	}
	
	return (
		<div>
		{imageGroups.map((group,idx) => ( <>
			{group.length > 0 && (<><h3>{`${title[idx]}`}</h3>
			<View style={{justifyContent: 'center', display: 'flex',
							flexDirection: 'row', flexWrap: 'wrap', gap: '20px' }}>
				{group.map((url,j) => (
					<>
						<View style={{justifyContent: 'center', alignItems: 'center', display: 'flex',
										flexDirection: 'column', flexWrap: 'wrap',}}>
							<img
							key={`${j}`}
							src={url.imageLinks[0]}
							alt={PrintInfo(url, idx)}
							className="background-image"
							style={returnStyle(url[COL.EXTRA_INFO])}
							onClick={() => screenWidth > 500 ? handleFull(url.imageLinks[0]) : undefined }
							/>
							{cell(url,COL.EXTRA_INFO).includes(NSFW_MARKER) && (
							<span
								style={{
									position: "absolute",
									top: "10px",
									color: "red",
									fontWeight: "bold",
									fontSize: "50px",
									textShadow: "4px 2px 6px rgba(0,0,0,1)",
								}}
								>
								18+ content
							</span>)}
							{(url.imageLinks.length > 1 || cell(url,COL.EXTRA_INFO).length > 0) && (
								<button
								style={styles.conk}
								  onClick={() =>
									handleOpen({ images: url.imageLinks.slice(1), text: cell(url,COL.EXTRA_INFO) })
								  }
								>
								  More
								</button>
							 	)}
							<Text style={styles.entryText}>{PrintInfo(url, idx)}</Text>
						</View >
					</>
				))}
			</View ></>)}
			</>))}
			
			{popupData && (
				<div className="popup-overlay" onClick={handleClose}>
				  <div className="popup-content" onClick={(e) => e.stopPropagation()}>
					{popupData.images.length > 0 && (
					<img
					  src={popupData.images[currentIndex]}
					  alt={`Example nr ${currentIndex + 1}`}
					  className="popup-image"
					  style={returnStyle(popupData.text)}
					  onClick={() => screenWidth > 500 ? handleFull(popupData.images[currentIndex]): undefined}
					/>)}
					{popupData.images.length > 1 && (
					  <div className="slider-buttons">
						<button onClick={showPrev}>◀</button> 
						<button onClick={showNext}>▶</button>
					  </div>
					)}
					<LinkText text={popupData.text} />
					<button className="exit-button" onClick={handleClose}>X</button>
				  </div>
				</div>
			  )}

			  {isFullImage && (
				<div className="popup-overlay" onClick={() => setIsFullImage(false)}>
					<img
					src={fullImage}
					className="modal-image"
					alt="Full image"
					onClick={() => setIsFullImage(false)}
					/>
				</div>
			  )}
		</div>
	);
};



export default ImageGroup;