import React from "react";
import "./GradientButton.css";

export default function GradientButton({ setShowThanks , setShowInfo }) {
  return (
	<>
		<button className="gradient-btn" onClick={() => setShowInfo(prev => !prev)}>
		  <span className="circle-icon-neonblue"></span>
		  <span className="btn-text">INFO</span>
		</button>
		<button className="gradient-btn" onClick={() => setShowThanks(prev => !prev)}>
		  <span className="circle-icon-purple"></span>
		  <span className="btn-text">SPECIAL THANKS</span>
		</button>
	</>
  );
}
