function App() {
 	
  // State to keep track of which div is shown
	const [selectedDiv, setSelectedDiv] = useState(null);
	const [optionValue, setOptionValue] = useState(null);
	const [disabled, setDisabled] = useState(false);

	const [loading, setLoading] = useState(false);
	const [imagesLoaded, setImagesLoaded] = useState(0);
	const [totalImages, setTotalImages] = useState(0);
	const [showImages, setShowImages] = useState(false);
	const [showInfo, setShowInfo] = useState(false);
	const [showThanks, setShowThanks] = useState(false);
	
	const [imageGroups, setImageGroups] = useState([]);

	//const [data, setData] = useState([]);
	const [csvData, setCsvData] = useState([]);
	const [lastModified, setLastModified] = useState(null);
	const [topTenSeries, setTopTenSeries] = useState([]);
	//const [headers, setHeaders] = useState([]);

	const extractImageUrls = (text) => {
		if(!text) return [];
		const urlRegex = /https?:\/\/\S+\.(?:jpg|jpeg|png|gif)/gi;
    return text.match(urlRegex) || [];
  };


  useEffect(() => {
	  
	  fetch('fileStorage/Top_Series_List.csv')
	  .then(response => response.text())
	  .then(listText => {	  
	  Papa.parse(listText, {
				  header: true,
				  skipEmptyLines: true,
				  complete: (result) => {
					  setTopTenSeries(result.data.slice(0,10));
				  }
			});
		});

	fetch('fileStorage/Evidence_export.csv')
		  .then(response => response.text())
		  .then(text => {
			  
			 const lines = text.split("\n");
			 
			 const firstLine = lines[0].trim();
			 if(firstLine.startsWith("#"))
			 {
				 const match = firstLine.match(/last_updated:\s*(.+)/i);
				 if(match && match[1]){
					 setLastModified(match[1]);
				 }
			 }
			  
			  const csvText = lines.filter((line) => !line.startsWith("#")).join("\n");
			  
			Papa.parse(csvText, {
			  header: true,
			  skipEmptyLines: true,
			  complete: (result) => {
				  const enhancedData = result.data.map((item) => {
					  const imageLinks = [];
					  const cleanedItem = {};

					  Object.entries(item).forEach(([key, value]) => {
						if (typeof value === 'string') {
						  // Hämta bildlänkar från cellen
						  const found = extractImageUrls(value);
						  if (found.length > 0) {
							imageLinks.push(...found);
							// Ta bort länkarna från texten
							let cleanedValue = value;
							found.forEach((url) => {
							  cleanedValue = cleanedValue.replace("[" + url + "]", '').trim();
							});
							cleanedItem[key] = cleanedValue;
						  } else {
							cleanedItem[key] = value;
						  }
						} else {
						  cleanedItem[key] = value;
						}
					  });

					  return { ...cleanedItem, imageLinks };
					});

				setCsvData(enhancedData);
				//console.log("enhancedData", enhancedData);
			  }
			});
		  })

/***
    // fetch('fileStorage/Crossover_Cameos_in_Anime_Evidence_List_Only.xlsx')
      // .then(res => res.arrayBuffer())
      // .then(arrayBuffer => {
        // const workbook = XLSX.read(arrayBuffer, { type: 'array' });
        // const sheet = workbook.Sheets[workbook.SheetNames[0]];
        // const allData = XLSX.utils.sheet_to_json(sheet, { header: 1 });
		// // const allDefaultLinkData = Object.entries(sheet)
										// // .filter(([key]) => key.startsWith("E"))
										// // .map(([_, value]) => value)
										// // .map(item => item.l)
										// // .filter(lValue => lValue !== undefined);
		// const findTheGuilty = Object.entries(sheet)
										// .filter(([key]) => key.startsWith("E"))
										// .map(([_, value]) => value)
										// .map(item => Object.keys(item).length);
										
		// const allCommentsLinkData = Object.entries(sheet)
										// .filter(([key]) => key.startsWith("G"))
										// .map(([_, value]) => value)
										// .map(item => item.l)
										// .filter(lValue => lValue !== undefined);
		
		
        // const [headerRow,...dataRows] = allData;
		
		
		// dataRows.map(item => {
			// const match = allCommentsLinkData.find(obj => obj.ref === "G" + item[9]);
			// //if(item[9] === 542){ console.log("match:", match);};
			// const addLink = match?.Target ?? null;
		// return item.push([addLink]);});
			
		
		// //dataRows.map((item, index) => { const addLink = allCommentsLinkData[index]?.Target ?? null; return item.push(addLink);});

		// console.log("sheet:",sheet);
		// console.log("dataRows:",dataRows);
		// //console.log("findTheGuilty:", findTheGuilty);
		// //console.log("allDefaultLinkData:", allDefaultLinkData);
		// console.log("allCommentsLinkData:", allCommentsLinkData);
		
        // setHeaders(headerRow);
        // setData(dataRows);

      // })
	  ***/
      .catch(err => console.error("Could not load the data:", err));

  }, []);
  
	const handleLoadImages = () => {
		setImagesLoaded(prev => {
			const newCount = prev + 1;
			if( newCount === totalImages){
				const element = document.getElementById("scanningData");
				element?.scrollIntoView({behavior: "smooth"});
				setLoading(false);
				setShowImages(true);
			}
			return newCount;
		});
	};
	
	const handleImageError = (event) => {
		console.warn("Couldn't load entry:", event.target.src);
		handleLoadImages();
	}
	
	const monthMap = {
		January: 1, February: 2, March: 3, April: 4,
		May: 5, June: 6, July: 7, August: 8,
		September: 9, October: 10, November: 11, December: 12
	};

	const toComparableDate = (dateStr) => {
		const raw = String(dateStr ?? "").trim();
		if(!raw) return Number.MAX_SAFE_INTEGER;
		
		const [monthName, yearStr] = dateStr.split(',').map(s => s.trim());
		const month = monthMap[monthName];
		const year = parseInt(yearStr, 10);
			return year * 100 + month; // t.ex. maj 1982 => 198205
	};

  
	const combineDuplicates = (dataList) => {
	  const grouped = {}
	  
	 // console.log("dataList:", dataList);
	  
	  for ( const row of dataList){
		  const key = row.imageLinks[0];
		  if(!grouped[key]){
			  grouped[key] = [row];
		  }
		  else {
			grouped[key].push(row);
		  }
	  }
	  
	  const retVal = [];
	  
	  for(const key in grouped){
		  const group = grouped[key];
		  
		  if(group.length === 1) {
			  retVal.push(group[0]);
		  }
		  else {
			  //console.log("group", group);
			  const combined = {...group[0]};
			  combined[COL.EXTRA_INFO] = [...new Set(group.map(item => item[COL.EXTRA_INFO]).flat())].join("\n");
			  combined[COL.WHEN] = [...new Set(group.map(item => item[COL.WHEN]).flat())].join(", ");
			  combined['imageLinks'] = [...new Set(group.map(item => item['imageLinks']).flat())];
			  combined[COL.WHO_WHAT] = [...new Set(group.map(item => item[COL.WHO_WHAT]).flat())].join(", ").replace(" & ", ", ").replace(/, ([^,]*)$/, " & $1");
			  //console.log("combined", combined);
			  retVal.push(combined);
		  }
	  }
	  
	  retVal.sort((a, b) => {
		const dateA = toComparableDate(a[COL.MONTH_YEAR]);
		const dateB = toComparableDate(b[COL.MONTH_YEAR]);
		if (dateA === dateB) {
		  return String(a[COL.WHEN]).localeCompare(String(b[COL.WHEN]));
		}
		return dateA - dateB;
	  });
	  
	  return retVal;
  };

	const handleSelectChange = (optionSelected) => {
		const name = optionSelected?.value ?? null;

		if (name) {
			setLoading(true);
			setDisabled(true);
			setImagesLoaded(0);
			setShowImages(false);
			
			const allReference = [
				combineDuplicates(csvData.filter(row => cell(row, COL.LEVEL) === LEVEL_CROSSOVER &&
				(cell(row, COL.SERIES) ===  name || cell(row, COL.FROM_SERIES) ===  name))),
				combineDuplicates(csvData.filter(row => cell(row, COL.SERIES) ===  name && cell(row, COL.LEVEL) !== LEVEL_CROSSOVER)),
				combineDuplicates(csvData.filter(row => cell(row, COL.FROM_SERIES) ===  name && cell(row, COL.LEVEL) !== LEVEL_CROSSOVER)),
			];

			setImageGroups(allReference);
			const count = allReference.flat().length;
			setTotalImages(count);
			
		}

	};
  
  const customFilter = (option, inputValue) => {
	  const search = inputValue.toLowerCase();
	  const labelMatch = option.label.toLowerCase().includes(search);
	  const aliasMatch = option.data.aliases?.some(alias => alias.toLowerCase().includes(search));
	  
	  return labelMatch || aliasMatch;
  }
  
  return (
	<div className="App">
		<header className="App-select-header">
			<div className="App-logo"></div>
			<GradientButton setShowThanks={setShowThanks} setShowInfo={setShowInfo}/>
			<label htmlFor="dropdown" className="App-label" >CHOOSE YOUR SERIES:</label>
			<Select classNamePrefix="App-option" styles={{ fontSize: "12px", width: "500px" }}
				id="dropdown" options={Series}
				value={optionValue}
				onChange={(options) => {setSelectedDiv(options); handleSelectChange(options); setOptionValue(options);}}
				placeholder="Search..."  isClearable
				filterOption={customFilter} disabled={disabled}
			/> 
		</header>
		<header className="App-header">
			{/*<BildThreemap />*/}
			{loading && (<> <img className="App-loading" id="scanningData" src={okinuLoading} alt={"SCANNING DATA..."} /> <p>SCANNING DATA...</p></>)}
			{!selectedDiv?.label && !loading && (<>
			<CurvedTitle />
			<TopSeries Series={Series}
			topTenSeries={topTenSeries} 
			setSelectedDiv={setSelectedDiv}
			handleSelectChange={handleSelectChange}
			setOptionValue={setOptionValue}/></>)}
			{!loading && showImages && selectedDiv?.label && (
			<ImageGroup title={[`Crossovers`, `Cameos in ${selectedDiv.label}`, `Cameos of ${selectedDiv.label} characters`]}
			 imageGroups={imageGroups} isVisible={showImages} />)}
			{loading && imageGroups.flat().map((src, i) => (
				<img
				key={`preload-${i}`}
				src={src.imageLinks[0]}
				onLoad={handleLoadImages}
				onError={handleImageError}
				style={{
					display: 'none',
				}}
				alt="Preload"
				/>
			))}
			{showInfo && (<>
				<div className="App-popup-overlay" onClick={() => setShowInfo(false)} >
				  <div className="App-info-content" onClick={(e) => e.stopPropagation()}>
					<p className="App-special-thanks-info">{[...InfoList,
					lastModified !== null ? "Last updated: " + lastModified : ""].join("\n")}</p>
					<button className="App-exit-button" onClick={() => setShowInfo(false)}>X</button>
				  </div>
				</div>
			</>	
			)}
			{showThanks && (<>
				<div className="App-popup-overlay" onClick={() => setShowThanks(false)} >
				  <div className="App-special-thanks-content" onClick={(e) => e.stopPropagation()}>
					<div><p className="App-special-thanks-info">{SpecialThanks.join("\n")}</p></div>
					<button className="App-exit-button" onClick={() => setShowThanks(false)}>X</button>
				  </div>
				</div>
				</>
			)}
		</header>
    </div>
  );
}

export default App;
