// CurvedTitle.jsx
import React from 'react';
import './CurvedTitle.css';

export default function CurvedTitle() {
  return (
    <div className="svg-container">
      <svg viewBox="0 0 700 250" preserveAspectRatio="xMidYMid meet" className="responsive-svg">
        <defs>
          <path
            id="curve1"
            d="M 50 100 Q 350 0, 650 100"
            fill="transparent"
          />
          <path
            id="curve2"
            d="M 50 180 Q 350 80, 650 180"
            fill="transparent"
          />
          <linearGradient id="rainbowGradient" x1="0%" y1="0%" x2="100%" y2="0%">
            <stop offset="0%" stopColor="#FF0000" />
            <stop offset="40%" stopColor="#FFA500" />
            <stop offset="90%" stopColor="#FFFF00" />
          </linearGradient>
        </defs>

        <text
          fontSize="clamp(30px, 4vw, 30px)"
          fill="url(#rainbowGradient)"
          fontFamily="'Comic Sans MS', cursive"
        >
          <textPath href="#curve1" startOffset="50%" textAnchor="middle">
            Top 10 Series with the
          </textPath>
        </text>

        <text
          fontSize="clamp(40px, 4vw, 40px)"
          fill="url(#rainbowGradient)"
          fontFamily="'Comic Sans MS', cursive"
        >
          <textPath href="#curve2" startOffset="50%" textAnchor="middle">
            Most Cameos/Crossovers
          </textPath>
        </text>
      </svg>
    </div>
  );
}
